{"content":"// Pure chat logic: no VS Code imports, so it can be unit tested with node --test.

export interface ChatMessage {
  role: "user" | "assistant";
  text: string;
}

/** True when the text has something to send (not blank). */
export function canSend(text: string): boolean {
  return text.trim().length > 0;
}

/** Append a message, returning a new list (does not mutate the input). */
export function appendMessage(messages: ChatMessage[], message: ChatMessage): ChatMessage[] {
  return [...messages, message];
}

/** Fake assistant reply used until the chat is wired to Muse Code. */
export function formatEcho(text: string): string {
  return `Echo: ${text}`;
}

/**
 * Validate an unknown webview message. Returns the trimmed text to answer,
 * or undefined when the message isn't a sendable "send" message.
 */
export function parseSendMessage(value: unknown): string | undefined {
  if (typeof value !== "object" || value === null) {
    return undefined;
  }
  const { type, text } = value as { type?: unknown; text?: unknown };
  if (type !== "send" || typeof text !== "string") {
    return undefined;
  }
  const trimmed = text.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}
","path":"extension/src/lib/chat.ts"}

{"content":"// Random nonce for the webview Content-Security-Policy. No VS Code imports.

const ALPHABET = "[redacted]";

export function createNonce(length = 32): string {
  let out = "";
  for (let i = 0; i < length; i += 1) {
    out += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
  }
  return out;
}
","path":"extension/src/lib/nonce.ts"}

{"content":"import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { appendMessage, canSend, formatEcho, parseSendMessage } from "../lib/chat";
import { createNonce } from "../lib/nonce";

describe("canSend", () => {
  it("accepts plain text", () => {
    assert.equal(canSend("hi"), true);
  });

  it("rejects blank text", () => {
    assert.equal(canSend(""), false);
    assert.equal(canSend("   "), false);
    assert.equal(canSend("\n\t "), false);
  });
});

describe("appendMessage", () => {
  it("appends without mutating the input", () => {
    const before = [{ role: "user" as const, text: "hi" }];
    const after = appendMessage(before, { role: "assistant", text: "Echo: hi" });

    assert.equal(after.length, 2);
    assert.equal(before.length, 1);
    assert.deepEqual(after[1], { role: "assistant", text: "Echo: hi" });
  });
});

describe("formatEcho", () => {
  it("prefixes the text with Echo:", () => {
    assert.equal(formatEcho("hi"), "Echo: hi");
  });
});

describe("parseSendMessage", () => {
  it("accepts a send message", () => {
    assert.equal(parseSendMessage({ type: "send", text: "hi" }), "hi");
  });

  it("trims surrounding whitespace", () => {
    assert.equal(parseSendMessage({ type: "send", text: "  hi\n" }), "hi");
  });

  it("rejects blank text", () => {
    assert.equal(parseSendMessage({ type: "send", text: "   " }), undefined);
  });

  it("rejects other shapes", () => {
    assert.equal(parseSendMessage(undefined), undefined);
    assert.equal(parseSendMessage(null), undefined);
    assert.equal(parseSendMessage("send"), undefined);
    assert.equal(parseSendMessage({ type: "reply", text: "hi" }), undefined);
    assert.equal(parseSendMessage({ type: "send" }), undefined);
    assert.equal(parseSendMessage({ type: "send", text: 42 }), undefined);
  });
});

describe("createNonce", () => {
  it("returns 32 alphanumeric characters by default", () => {
    assert.match(createNonce(), /^[A-Za-z0-9]{32}$/);
  });

  it("returns unique values", () => {
    assert.notEqual(createNonce(), createNonce());
  });
});
","path":"extension/src/test/chat.test.ts"}

{"content":"import * as fs from "node:fs";
import * as path from "node:path";
import * as vscode from "vscode";
import { formatEcho, parseSendMessage } from "./lib/chat";
import { createNonce } from "./lib/nonce";

export class ChatViewProvider implements vscode.WebviewViewProvider {
  public static readonly viewType = "metaBetta.chat";

  private view?: vscode.WebviewView;

  public constructor(private readonly extensionUri: vscode.Uri) {}

  public resolveWebviewView(webviewView: vscode.WebviewView): void {
    this.view = webviewView;
    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [vscode.Uri.joinPath(this.extensionUri, "media")],
    };
    webviewView.webview.html = this.buildHtml(webviewView.webview);
    webviewView.onDidDispose(() => {
      this.view = undefined;
    });
    webviewView.webview.onDidReceiveMessage((message: unknown) => {
      const text = parseSendMessage(message);
      if (text === undefined) {
        return;
      }
      void this.view?.webview.postMessage({ type: "status", text: "Thinking…" });
      // Fake reply for now; brief 02 wires this to Muse Code.
      setTimeout(() => {
        void this.view?.webview.postMessage({ type: "reply", text: formatEcho(text) });
      }, 300);
    });
  }

  private buildHtml(webview: vscode.Webview): string {
    const mediaPath = path.join(this.extensionUri.fsPath, "media");
    const html = fs.readFileSync(path.join(mediaPath, "chat.html"), "utf8");
    const styleUri = webview.asWebviewUri(vscode.Uri.joinPath(this.extensionUri, "media", "chat.css"));
    const scriptUri = webview.asWebviewUri(vscode.Uri.joinPath(this.extensionUri, "media", "chat.js"));
    return html
      .replaceAll("__CSP_SOURCE__", webview.cspSource)
      .replaceAll("__STYLE_URI__", styleUri.toString())
      .replaceAll("__SCRIPT_URI__", scriptUri.toString())
      .replaceAll("__NONCE__", createNonce());
  }
}
","path":"extension/src/chatView.ts"}

{"content":"import * as vscode from "vscode";
import { ChatViewProvider } from "./chatView";

export function activate(context: vscode.ExtensionContext): void {
  const provider = new ChatViewProvider(context.extensionUri);
  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider(ChatViewProvider.viewType, provider),
    vscode.commands.registerCommand("metaBetta.open", async () => {
      await vscode.commands.executeCommand("metaBetta.chat.focus");
    }),
  );
}

export function deactivate(): void {
  // Nothing to clean up yet.
}
","path":"extension/src/extension.ts"}

