          if (list) {
            out.push("</" + list + ">");
          }
          out.push("<" + kind + ">");
          list = kind;
        }
        out.push("<li>" + content + "</li>");
      } else {
        if (list) {
          out.push("</" + list + ">");
          list = null;
        }
        out.push(content);
