1|// Spike 3: can we really stop a running turn?
2|// MuseClient keeps its connection private, so we build the client around a
3|// connection we spawn ourselves (the same steps MuseClient.spawn() takes), keep
4|// that connection, and send turn/interrupt mid-reply.
5|// Usage: node stop.mjs
6|import { MuseClient, spawnMspConnection, readSessionDurability } from "@muse-code/sdk";
7|import { mkdirSync } from "node:fs";
8|
9|const museBin = process.env.MUSE_BIN ?? "muse";
10|const workspaceRoot = process.env.MUSE_WS ?? "C:\\muse-play\\spike-ws";
11|const stopAfterMs = Number(process.env.STOP_AFTER_MS ?? 4000);
12|
13|mkdirSync(workspaceRoot, { recursive: true });
14|const handshake = spawnMspConnection({ command: museBin, args: ["serve"] });
15|let spawned;
16|try {
17|  spawned = await handshake.initialize({ clientInfo: { name: "meta_betta_spike", version: "0.0.1" } });
18|} catch (error) {
19|  await handshake.close().catch(() => undefined);
20|  throw error;
21|}
22|const connection = spawned.connection;
23|const client = new MuseClient(connection, {
24|  durability: readSessionDurability(spawned.initializeResult),
25|  host: spawned,
26|});
27|
28|const session = await client.startSession({ workspaceRoot });
29|const turn = await session.sendUserTurn({
30|  input: [{ type: "text", text: "Write a 1500-word story about a mechanic and a parts counter. No tools." }],
31|});
32|console.log(`[turn ${turn.turnId} started, stopping in ${stopAfterMs} ms]`);
33|
34|let chars = 0;
35|const stream = (async () => {
36|  for await (const d of turn.deltas()) chars += (typeof d === "string" ? d : (d.text ?? d.delta ?? "")).length;
37|})();
38|
39|await new Promise((r) => setTimeout(r, stopAfterMs));
40|const t0 = Date.now();
41|const ack = await connection.command("turn/interrupt", { sessionId: session.sessionId, turnId: turn.turnId });
