259|  public async openLink(url: string): Promise<void> {
260|    try {
261|      if (/^https?:/i.test(url)) {
262|        await vscode.env.openExternal(vscode.Uri.parse(url));
263|        return;
264|      }
265|      const folder = vscode.workspace.workspaceFolders?.[0];
266|      const link = folder ? parseFileLink(url, folder.uri.fsPath) : undefined;
