290|  private prepare(): Promise<void> {
291|    if (this.prepared) {
292|      return Promise.resolve();
293|    }
294|    this.preparing ??= this.doPrepare().finally(() => {
295|      this.preparing = undefined;
296|    });
297|    return this.preparing;
