300|  private async doPrepare(): Promise<void> {
301|    try {
302|      const folder = vscode.workspace.workspaceFolders?.[0];
303|      const savedId = this.storage.get<string>(SESSION_ID_KEY);
304|      if (!folder || !savedId?.trim()) {
305|        return;
306|      }
307|      const host = await this.ensureHost(folder);
308|      let shown = 0;
309|      try {
310|        shown = await host.prepare(folder.uri.fsPath);
311|      } catch {
312|        // Leave the panel usable; send() surfaces startup problems properly.
313|        shown = 0;
314|      }
315|      if (shown === 0) {
316|        const stored = cleanTranscript(this.storage.get<unknown>(TRANSCRIPT_KEY));
317|        stored.forEach((entry, index) => {
318|          this.recordAndBroadcast(
319|            entry.role === "user"
320|              ? { type: "user", text: entry.text }
321|              : { type: "assistant", id: `stored-${index}`, text: entry.text },
322|          );
323|        });
324|      }
325|    } finally {
326|      this.prepared = true;
327|    }
328|  }
