330|  private ensureHost(folder: vscode.WorkspaceFolder): Promise<MuseHost> {
331|    if (this.host) {
332|      return Promise.resolve(this.host);
333|    }
334|    // Single flight: two hosts would each spawn `muse serve` and their
335|    // status lines would overwrite each other.
336|    return this.createHostShared(folder);
337|  }
