345|  /**
346|   * Decide memory from the setting + Workspace Trust; create the brain and
347|   * front door when on. Returns the --trust-workspace flag for the host.
348|   */
349|  private async ensureMemory(folder: vscode.WorkspaceFolder): Promise<boolean> {
350|    const setting = vscode.workspace.getConfiguration("metaBetta").get<boolean>("memory", true);
351|    const on = setting && vscode.workspace.isTrusted;
352|    this.memoryOn = on;
353|    if (on) {
354|      await ensureBrain(folder.uri.fsPath);
355|      await ensureFrontDoor(folder.uri.fsPath);
356|    }
357|    if (!this.memoryAnnounced) {
358|      this.memoryAnnounced = true;
359|      // Ephemeral, like turn/status: announcing again on every reopen would
360|      // flood the history with the same line.
361|      if (on) {
362|        this.broadcast({ type: "notice", kind: "info", text: "Memory is on for this folder (brain/)." });
363|      } else if (!setting) {
364|        this.broadcast({
365|          type: "notice",
366|          kind: "info",
367|          text: "Memory is off. Turn it on with the Meta Betta › Memory setting.",
368|        });
369|      } else {
370|        this.broadcast({
371|          type: "notice",
372|          kind: "info",
373|          text: "Memory is off because VS Code doesn't trust this folder. Trust it (Manage Workspace Trust) to turn memory on.",
374|        });
375|      }
376|    }
377|    return on;
378|  }
379|
380|  private sessionLabel(): string {
381|    return formatSessionLabel(this.sessionId, this.sessionTopic);
382|  }
383|
384|  private broadcastSessionLabel(): void {
385|    this.broadcast({ type: "sessionLabel", label: this.sessionLabel() });
386|  }
387|
388|  private adoptStoredLabel(): void {
389|    // A resumed chat keeps its label; a chat already renamed or reset this
390|    // boot keeps what it has.
391|    if (this.labelSettled) {
392|      return;
393|    }
394|    this.labelSettled = true;
395|    const stored = cleanSessionLabel(this.storage.get<unknown>(SESSION_LABEL_KEY));
396|    if (stored) {
397|      this.sessionId = stored.id;
398|      this.sessionTopic = stored.topic;
399|      this.broadcastSessionLabel();
400|    }
401|  }
402|
403|  private persistSessionLabel(): void {
404|    this.labelSettled = true;
405|    this.storeSet(SESSION_LABEL_KEY, { id: this.sessionId, topic: this.sessionTopic });
406|  }
407|
408|  private createHost(trustWorkspace: boolean): MuseHost {
409|    return new MuseHost({
410|      museBin: findMuseBin(vscode.workspace.getConfiguration("metaBetta").get<string>("museBin", "")),
411|      version: readVersion(this.extensionUri),
412|      trustWorkspace,
413|      emit: (event) => this.onHostEvent(event),
414|      askApproval: (card) => this.askApproval(card),
415|      sessionStore: {
416|        loadId: () => this.storage.get<string>(SESSION_ID_KEY),
417|        saveId: (id) => this.storeSet(SESSION_ID_KEY, id),
418|        clear: () => {
419|          this.storeSet(SESSION_ID_KEY, undefined);
420|          this.storeSet(TRANSCRIPT_KEY, undefined);
421|        },
422|      },
423|    });
424|  }
425|
426|  private storeSet(key: string, value: unknown): void {
427|    void this.storage.update(key, value).then(undefined, () => undefined);
428|  }
429|
430|  private persistTranscript(): void {
431|    this.storeSet(TRANSCRIPT_KEY, buildTranscript(this.history));
432|  }
433|
434|  private onHostEvent(event: MuseHostEvent): void {
435|    if (event.type === "turn") {
436|      this.running = event.state === "started";
437|      this.broadcast(event);
438|      if (!this.running) {
439|        this.persistTranscript();
440|      }
441|      return;
442|    }
443|    if (event.type === "status") {
444|      this.lastStatus = event.text;
445|      this.broadcast(event);
446|      return;
447|    }
448|    if (event.type === "assistant" && this.running) {
449|      this.liveReplySeen = true;
450|    }
451|    this.recordAndBroadcast(event);
452|  }
453|
454|  private askApproval(card: ApprovalCardEvent): Promise<string | undefined> {
455|    if (this.sinks.size === 0 || !this.running) {
456|      return Promise.resolve(undefined);
457|    }
458|    return new Promise((resolve) => {
459|      this.approvalResolvers.set(card.id, resolve);
460|      this.recordAndBroadcast(card);
461|    });
462|  }
463|
464|  private recordAndBroadcast(event: TranscriptEvent): void {
465|    // Streaming updates replace their earlier self, so history stays compact
466|    // and a replay shows each bubble once, in its final state.
467|    const upsertId =
468|      event.type === "assistant" || event.type === "thinking" || event.type === "tool" ? event.id : undefined;
469|    if (upsertId !== undefined) {
470|      const index = this.history.findIndex(
471|        (entry) => entry.type === event.type && (entry as { id?: string }).id === upsertId,
472|      );
473|      if (index >= 0) {
474|        this.history[index] = event;
475|        this.broadcast(event);
476|        return;
477|      }
478|    }
479|    this.history.push(event);
480|    if (this.history.length > HISTORY_LIMIT) {
481|      this.history.splice(0, this.history.length - HISTORY_LIMIT);
482|    }
483|    this.broadcast(event);
484|    if (event.type === "user") {
485|      this.persistTranscript();
486|    }
487|  }
488|
489|  private broadcast(message: unknown): void {
490|    for (const sink of this.sinks) {
491|      sink.post(message);
492|    }
493|  }
494|}
495|
496|/** Route one webview message to the controller. Shared by panel and sidebar. */
497|export function routeViewMessage(controller: ChatController, message: unknown): void {
498|  if (!isRecord(message)) {
499|    return;
500|  }
501|  if (message.type === "stop") {
502|    controller.stop();
503|    return;
504|  }
505|  if (message.type === "newChat") {
506|    void controller.newChat();
507|    return;
508|  }
509|  if (message.type === "renameSession") {
510|    void controller.renameSession();
511|    return;
512|  }
513|  if (message.type === "openFolder") {
514|    void controller.openFolder();
515|    return;
516|  }
517|  if (message.type === "approve" && typeof message.id === "string" && typeof message.choiceId === "string") {
518|    controller.approve(message.id, message.choiceId);
519|    return;
520|  }
521|  if (message.type === "openLink" && typeof message.url === "string") {
522|    void controller.openLink(message.url);
523|    return;
524|  }
525|  const text = parseSendMessage(message);
526|  if (text !== undefined) {
527|    void controller.send(text);
528|  }
529|}
530|
531|function isRecord(value: unknown): value is Record<string, unknown> {
532|  return typeof value === "object" && value !== null;
533|}
534|
535|function readVersion(extensionUri: vscode.Uri): string {
536|  try {
537|    const packageJson = JSON.parse(
538|      fs.readFileSync(path.join(extensionUri.fsPath, "package.json"), "utf8"),
539|    ) as { version?: unknown };
540|    return typeof packageJson.version === "string" ? packageJson.version : "0.0.0";
541|  } catch {
542|    return "0.0.0";
543|  }
