1|import * as vscode from "vscode";
2|import { type ChatController, type ChatSink, routeViewMessage } from "./chatController.js";
3|import { buildChatHtml } from "./chatHtml.js";
4|
5|/** Where the chat lives, from the metaBetta.openIn setting. */
6|export function readOpenIn(): "editor" | "sidebar" {
7|  return vscode.workspace.getConfiguration("metaBetta").get<string>("openIn", "editor") === "sidebar"
8|    ? "sidebar"
9|    : "editor";
10|}
11|
12|export class ChatViewProvider implements vscode.WebviewViewProvider {
13|  public static readonly viewType = "metaBetta.chat";
14|
15|  private view?: vscode.WebviewView;
16|  private sink?: ChatSink;
17|  private mode?: "chat" | "blank";
18|
19|  public constructor(
20|    private readonly extensionUri: vscode.Uri,
21|    private readonly controller: ChatController,
22|    private readonly openPanel: () => void,
23|  ) {}
24|
25|  public resolveWebviewView(webviewView: vscode.WebviewView): void {
26|    this.view = webviewView;
27|    webviewView.webview.options = {
28|      enableScripts: true,
29|      localResourceRoots: [vscode.Uri.joinPath(this.extensionUri, "media")],
30|    };
31|    webviewView.onDidDispose(() => {
32|      this.unbindSink();
33|      this.view = undefined;
34|      this.mode = undefined;
35|    });
36|    webviewView.onDidChangeVisibility(() => {
37|      if (webviewView.visible) {
38|        this.sync();
39|      }
40|    });
41|    webviewView.webview.onDidReceiveMessage((message: unknown) => {
42|      routeViewMessage(this.controller, message);
43|    });
44|    this.sync();
45|  }
46|
47|  /**
48|   * Full chat when openIn is sidebar, otherwise a blank view: the icon just
49|   * opens the chat tab.
50|   */
51|  public sync(): void {
52|    const view = this.view;
53|    if (!view) {
54|      return;
55|    }
56|    if (readOpenIn() === "sidebar") {
57|      if (this.mode !== "chat") {
58|        this.unbindSink();
59|        view.webview.html = buildChatHtml(view.webview, this.extensionUri, "chat");
60|        const sink: ChatSink = {
61|          post: (message: unknown) => {
62|            void view.webview.postMessage(message);
63|          },
64|        };
65|        this.sink = sink;
66|        this.controller.bind(sink);
67|        this.mode = "chat";
68|      }
69|      return;
70|    }
71|    if (this.mode !== "blank") {
72|      this.unbindSink();
73|      view.webview.html = "<!DOCTYPE html><html><body></body></html>";
74|      this.mode = "blank";
75|    }
76|    if (view.visible) {
77|      this.openPanel();
78|    }
79|  }
80|
81|  private unbindSink(): void {
82|    if (this.sink) {
83|      this.controller.unbind(this.sink);
84|      this.sink = undefined;
85|    }
86|  }
87|}

