1|import * as vscode from "vscode";
2|import { buildChatHtml } from "../chatHtml.js";
3|import { brainCardInputs, buildBrainCards, ensureBrain, nodeBrainFs } from "./brain.js";
4|
5|export class BrainViewProvider implements vscode.WebviewViewProvider {
6|  public static readonly viewType = "metaBetta.brain";
7|
8|  private view?: vscode.WebviewView;
9|  private watcher?: vscode.FileSystemWatcher;
10|
11|  public constructor(private readonly extensionUri: vscode.Uri) {}
12|
13|  public resolveWebviewView(webviewView: vscode.WebviewView): void {
14|    this.view = webviewView;
15|    webviewView.webview.options = {
16|      enableScripts: true,
17|      localResourceRoots: [vscode.Uri.joinPath(this.extensionUri, "media")],
18|    };
19|    webviewView.webview.html = buildChatHtml(webviewView.webview, this.extensionUri, "brain");
20|    webviewView.onDidDispose(() => {
21|      this.view = undefined;
22|      this.watcher?.dispose();
23|      this.watcher = undefined;
24|    });
25|    webviewView.onDidChangeVisibility(() => {
26|      if (webviewView.visible) {
27|        void this.refresh();
28|      }
29|    });
30|    webviewView.webview.onDidReceiveMessage((message: unknown) => {
31|      if (
32|        typeof message === "object" &&
33|        message !== null &&
34|        (message as { type?: unknown }).type === "openBrainFile" &&
35|        typeof (message as { file?: unknown }).file === "string"
36|      ) {
37|        void this.openFile((message as { file: string }).file);
38|      }
39|    });
40|    const folder = vscode.workspace.workspaceFolders?.[0];
41|    this.watcher?.dispose();
42|    if (folder) {
43|      this.watcher = vscode.workspace.createFileSystemWatcher(
44|        new vscode.RelativePattern(folder, "brain/**"),
45|      );
46|      this.watcher.onDidCreate(() => void this.refresh());
47|      this.watcher.onDidChange(() => void this.refresh());
48|      this.watcher.onDidDelete(() => void this.refresh());
49|    }
50|    void this.refresh();
51|  }
52|
53|  public async refresh(): Promise<void> {
54|    const view = this.view;
55|    if (!view) {
56|      return;
57|    }
58|    const folder = vscode.workspace.workspaceFolders?.[0];
59|    if (!folder) {
60|      void view.webview.postMessage({ type: "brainStatus", text: "Open a folder to start." });
61|      return;
62|    }
63|    const inputs = brainCardInputs((file) => ({ mtimeMs: undefined, content: undefined }));
64|    const cards = buildBrainCards(
65|      await Promise.all(
66|        inputs.map(async (input) => {
67|          const target = vscode.Uri.joinPath(folder.uri, "brain", input.file);
68|          try {
69|            const [bytes, fileStat] = await Promise.all([
70|              vscode.workspace.fs.readFile(target),
71|              vscode.workspace.fs.stat(target),
72|            ]);
73|            return { ...input, mtimeMs: fileStat.mtime, content: new TextDecoder().decode(bytes) };
74|          } catch {
75|            return input;
76|          }
77|        }),
78|      ),
79|    );
80|    void view.webview.postMessage({ type: "brain", cards });
81|  }
82|
83|  private async openFile(file: string): Promise<void> {
84|    const folder = vscode.workspace.workspaceFolders?.[0];
85|    if (!folder) {
86|      return;
87|    }
88|    try {
89|      await ensureBrain(folder.uri.fsPath, nodeBrainFs);
90|      const uri = vscode.Uri.joinPath(folder.uri, "brain", file);
91|      try {
92|        await vscode.workspace.fs.stat(uri);
93|      } catch {
94|        if (!file.startsWith("log/")) {
95|          return;
96|        }
97|        await vscode.workspace.fs.writeFile(uri, new TextEncoder().encode(`# ${file.slice(4, -3)}\n`));
98|      }
99|      const document = await vscode.workspace.openTextDocument(uri);
100|      await vscode.window.showTextDocument(document);
101|    } catch {
102|      // Clicking a card that can't open stays quiet; the card is still there.
103|    }
104|  }
105|}

